WITH cleaned AS (SELECT *, COALESCE(job_title, 'N/A') job_title_filled, COALESCE(level, 'OTHER') level_filled FROM employees WHERE hire_date >= DATE '2023-08-04' AND job_title IS NOT NULL) SELECT id, job_title, hire_date, is_remote, level, level_filled, LAG(salary) OVER w_hist prev_salary, LEAD(salary) OVER w_hist next_salary, ROW_NUMBER() OVER w_hist seq_no FROM cleaned WINDOW w_hist AS (PARTITION BY job_title ORDER BY salary, id)
